{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Berkeley Rent Stabilization Ordinance rent-control coverage","requirement":"Rent control applies under Berkeley's Rent Stabilization Ordinance only to fully covered units: most multifamily properties built before 1980, single-family homes with tenancies begun before 1996, and rooming houses. Partially covered and exempt units are not rent-controlled.","key_value":null,"coverage_conditions":"Fully covered: most multifamily units built before 1980; single-family homes with tenancies begun before 1996; rooming houses with five or more rooms. Other unit types are partially covered (no rent control) or exempt.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1980-06","basis":"certificate_of_occupancy"},{"type":"owner","role":"exempt","who":"owner-occupied","unit_limit":2},{"type":"other","role":"exempt","text":"Most condominiums"},{"type":"other","role":"exempt","text":"Section 202, Section 811, Rental Supplement, Section 8 Loan Management Set Aside or Project-based Section 8 subsidies in a HUD-insured project"}],"per_tenancy":"Single-family home with a tenancy that began on or after January 1, 1996; tenancy started after Nov 7, 2018 in an owner-occupied property with an ADU; unit where the owner shares a kitchen or bath with the tenant.","coverage_quotes":["Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","University rental units such as dormitories. Exempt No No No No","Nonprofit Cooperative Exempt No No No No"]},"exemptions":"Golden Duplex; unit where owner shares kitchen or bath with tenant; post-Nov 7, 2018 ADU tenancies in owner-occupied property; university rental units such as dormitories; nonprofit cooperatives. Partially covered unit types are also excluded from rent control.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley Rent Stabilization and Eviction for Just Cause Ordinance coverage","requirement":"Landlords of covered units may evict only for just cause. Exempt unit types, including owner-occupied Golden Duplexes, owner-shared units, and nonprofit cooperatives, are not covered by the just cause requirement.","key_value":null,"coverage_conditions":"All residential units except the exemptions: Golden Duplex, owner-shared kitchen/bath unit, post-Nov 7 2018 ADU tenancies in an owner-occupied property, university rental units such as dormitories, and nonprofit cooperatives.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"owner-occupied","unit_limit":2},{"type":"other","role":"exempt","text":"Nonprofit cooperative"}],"per_tenancy":"Unit where the owner shares a kitchen or bath with the tenant if the owner lived on the property when the tenancy started; tenancies started after Nov 7, 2018 on properties where one unit is an ADU and either unit is owner-occupied.","coverage_quotes":["Nonprofit Cooperative Exempt No No No No","University rental units such as dormitories. Exempt No No No No","Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes"]},"exemptions":"Golden Duplex; unit where owner shares kitchen or bath with tenant; post-Nov 7, 2018 ADU tenancies in owner-occupied property; university rental units such as dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley Rent Ordinance security deposit interest coverage","requirement":"Landlords of covered units must pay interest on tenants' security deposits as required by the Ordinance. Exempt unit types, including Golden Duplexes, owner-shared units, university dormitories and nonprofit cooperatives, are not covered.","key_value":null,"coverage_conditions":"All residential units except the exemptions: Golden Duplex, owner-shared kitchen/bath unit, post-Nov 7 2018 ADU tenancies in an owner-occupied property, university rental units such as dormitories, and nonprofit cooperatives.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"owner-occupied","unit_limit":2},{"type":"other","role":"exempt","text":"Nonprofit cooperative"}],"per_tenancy":"Unit where the owner shares a kitchen or bath with the tenant if the owner lived on the property when the tenancy started; tenancies started after Nov 7, 2018 on properties where one unit is an ADU and either unit is owner-occupied.","coverage_quotes":["Nonprofit Cooperative Exempt No No No No","University rental units such as dormitories. Exempt No No No No","Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes"]},"exemptions":"Golden Duplex; unit where owner shares kitchen or bath with tenant; post-Nov 7, 2018 ADU tenancies in owner-occupied property; university rental units such as dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
